import {VERSION,BASE_COMMIT,newProject,demoProject,record,validateProject,strictRows,strictSettings,permissionStatus,requirePermission,addSource,validateSource,addCases,reviewCase,approveFix,currentReview,hint,quality,economics,sensitivity,decision,importProject,serializeProject,parseWorkloadCSV,parseCaseCSV,reportHTML,escapeHTML,fmtMoney,fmtNumber,percent} from './domain.js';

const E=escapeHTML,$=id=>document.getElementById(id),root=$('app');
const STORAGE_KEY='pilotverdict.integrated.v0.5';
let project=null,route='home',dirty=false,validationTab='cases',caseId=null,scenarioFilter='ai',stageFilter='baseline',sourceEdit=null,caseDraft=null;
let flashTimer;
const isPercent=new Set(['productiveFraction','realizationRate','rulesCoverage','rulesTimeReduction','aiCoverage','aiTimeReduction']);
const SETTINGS=[
 ['laborCostHour','Labor cost per paid hour','USD / hour',28],['productiveFraction','Productive share of paid time','Percent',75],['realizationRate','Capacity that becomes avoided spending','Percent; zero unless supported',0],['months','Evaluation horizon','Months, 1–60',12],
 ['rulesCoverage','Rules: eligible contact share','Percent',34],['rulesTimeReduction','Rules: time reduction on eligible contacts','Your estimated percentage',55],['rulesExtraQA','Rules: review time per eligible contact','Minutes; excludes correction time',.04],['rulesMonthly','Rules: recurring cost','USD / month',60],['rulesSetup','Rules: implementation cost','USD once',300],
 ['aiCoverage','AI: eligible contact share','Percent',58],['aiTimeReduction','AI: time reduction on eligible contacts','Your estimated percentage',75],['aiExtraQA','AI: review time per eligible contact','Minutes; excludes correction time',.12],['aiFixedMonthly','AI: recurring fixed cost','USD / month',250],['aiCostTicket','AI: usage cost per eligible contact','USD / contact',.45],['aiSetup','AI: implementation cost','USD once',1500],
 ['rulesInitialInvestment','Rules: other initial investment','USD once; additional to setup',0],['aiInitialInvestment','AI: other initial investment','USD once; additional to setup',0]
];
const pill=(text,type='')=>`<span class="pill ${type}">${E(text)}</span>`;
const button=(label,action,kind='secondary',attrs='')=>`<button type="button" class="button ${kind}" data-action="${action}" ${attrs}>${label}</button>`;
function field(name,label,value='',hintText='',options={}){
 const type=options.type||'text',extra=options.extra||'';
 return `<label class="field ${options.full?'full':''}" for="${name}">${E(label)}${hintText?`<span>${E(hintText)}</span>`:''}<input id="${name}" name="${name}" type="${type}" value="${E(value??'')}" ${extra}></label>`;
}
function area(name,label,value='',hintText='',full=true){return `<label class="field ${full?'full':''}" for="${name}">${E(label)}${hintText?`<span>${E(hintText)}</span>`:''}<textarea id="${name}" name="${name}" maxlength="3000">${E(value||'')}</textarea></label>`;}
function select(name,label,value,options,hintText=''){return `<label class="field" for="${name}">${E(label)}${hintText?`<span>${E(hintText)}</span>`:''}<select id="${name}" name="${name}">${options.map(([v,t])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;}
const check=(name,label,value=false)=>`<label class="check" for="${name}"><input type="checkbox" name="${name}" id="${name}" ${value?'checked':''}><span>${E(label)}</span></label>`;
const labelForScenario=s=>s==='ai'?'AI assistance':s==='rules'?'Rules-based automation':'Current process';
const stageOptions=[['baseline','Before change'],['retest','After change'],['additional','Extra checks']];
function notify(message,error=false){clearTimeout(flashTimer);$('flash').textContent=message;$('flash').className=error?'error':'';$('flash').hidden=false;if(!error)flashTimer=setTimeout(()=>$('flash').hidden=true,6500);}
function fail(error){const msg=error instanceof Error?error.message:String(error);const el=$('page-error');if(el){el.textContent=msg;el.setAttribute('tabindex','-1');el.focus();}notify(msg,true);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function confirmReplace(){return !project||window.confirm('Replace the project currently in memory? Export JSON or save it in this browser first to keep your work.');}
function commit(p,message,newRoute=route){project=p;dirty=false;if(newRoute!==route){location.hash=newRoute;}else render();if(message)notify(message);}
function routeTo(next){if(next===route){render();return;}location.hash=next;}
function start(fictional=false){if(!confirmReplace())return;project=newProject({fictional});dirty=false;caseId=null;validationTab='sources';routeTo('project');}
function loadDemo(){if(!confirmReplace())return;project=demoProject();dirty=false;caseId='baseline-01';validationTab='cases';scenarioFilter='ai';stageFilter='baseline';routeTo('economics');notify('Example loaded. Change the inputs to explore your options.');}
function workspaceHead(){
 const steps=[['project','Your work'],['economics','Costs'],['validation','Check answers'],['decision','Results']];
 return `<div class="workspace-head"><div><p class="kicker">${project.mode==='fictional'?'EXAMPLE DATA':'YOUR PROJECT'}</p><h1>${E(project.title||'Start with one task')}</h1></div><div class="actions">${button('Save project','save-local')}<details class="project-menu"><summary>More options</summary><div class="menu-items">${button('Download project','export-project','quiet')}${button('Open saved project','load-local','quiet')}${button('New project','new-project','quiet')}${button('Delete saved project','clear-local','quiet')}</div></details></div></div><nav class="subnav" aria-label="Your analysis">${steps.map(([r,label],i)=>`<a href="#${r}" ${route===r?'aria-current="page"':''}><span class="step-no">${i+1}</span>${label}</a>`).join('')}</nav>${project.imported?'<p class="fine">Project opened. Results are recalculated from its inputs.</p>':''}<div id="page-error" class="inline-error" role="alert"></div>`;
}
function blocked(){const s=permissionStatus(project);return s.ok?'':`<div class="notice warning"><strong>Complete your project setup.</strong>${E(s.reason)} <a href="#project">Complete the project record</a>.</div>`;}
function home(){
 const e=economics(demoProject());
 return `<section class="pv48-public-hero" aria-labelledby="pv48-title"><h1 id="pv48-title"><span class="pv48-serif">Your AI workflow.</span> <span class="pv48-blue">Know the cost.</span> Check the answers.</h1><p>See whether AI could save you time and money.<br class="pv48-desktop-break"> Compare costs, check answers against your rules, and decide what to improve.</p><div class="pv48-main-actions"><button class="pv48-button pv48-primary" data-action="start-real">Start analysis <span aria-hidden="true">→</span></button><button class="pv48-button pv48-secondary" data-action="load-demo">See an example</button></div><p class="pv48-under-cta">Use your own numbers or start with the example.</p></section>
 <section class="pv48-public-peek" id="product"><div class="pv48-browser"><div class="pv48-window-top"><span class="pv48-dots" aria-hidden="true"><i></i><i></i><i></i></span>PilotVerdict · Refund support</div><div class="pv48-browser-content"><aside class="pv48-peek-sidebar"><b>PilotVerdict</b><button data-action="peek-costs" class="pv48-peek-active" aria-pressed="true">Costs</button><button data-action="peek-answers" aria-pressed="false">Answers</button><button data-action="peek-next" aria-pressed="false">Next step</button></aside><div class="pv48-peek-body"><div class="pv48-peek-heading"><div><h2>Should we automate refund support?</h2><p>Compare the options. Check what needs fixing.</p></div><span class="pv48-sample-chip">Example data</span></div>
 <div data-peek="costs"><div class="pv48-peek-choices"><span class="selected">Estimated result over 12 months</span></div><div class="pv48-peek-grid">${e.scenarios.map(x=>`<section><h3>${x.id==='current'?'Keep the current process':x.id==='rules'?'Use rules-based automation':'Use AI assistance'}</h3><p><strong class="peek-value">${E(fmtMoney(x.netHorizon))}</strong><br>${x.id==='current'?'The starting point for comparison.':x.netHorizon>=0?'Estimated benefit after added costs.':'Added costs outweigh the estimated savings.'}</p></section>`).join('')}</div><p class="pv48-peek-policy">Change the workload, prices or correction time to see how the comparison changes.</p></div>
 <div data-peek="answers" hidden><div class="pv48-peek-choices"><span class="selected">A refund above the approved limit</span></div><div class="pv48-peek-grid"><section><h3>Your rule</h3><p>Refunds above $20 need approval from the billing lead.</p></section><section><h3>The AI answer</h3><p>“Yes, I can issue the full $85 refund. It is approved.”</p></section><section><h3>What needs attention</h3><p><strong>Check the promised refund.</strong><br>The answer promises more than the approved limit.</p></section></div><p class="pv48-peek-policy">Review the answer beside its source, record your decision, then check the corrected version.</p></div>
 <div data-peek="next" hidden class="pv49-peek-alt"><h3>Fix the answer. Recheck the cost.</h3><p>Record a clearer approval rule, compare the new answers and include the time spent correcting them in your cost estimate.</p><p>Keep the numbers, review notes and next steps together in one report.</p><button class="pv48-button pv48-primary" data-action="load-demo">Open this example →</button></div></div></div></div></section>
 <section class="pv48-how" id="how-it-works"><div class="pv48-how-intro"><p class="pv48-small-kicker">One project, from your inputs to your next step</p><h2><span class="pv48-serif">Understand the trade-offs.</span> Choose what to do.</h2></div><div class="pv48-how-grid"><article><span>01</span><h3>Describe your work</h3><p>Start with a task your team handles. Enter your numbers or import a file.</p></article><article><span>02</span><h3>Compare and check</h3><p>Compare costs with and without AI. Check its answers against your rules.</p></article><article><span>03</span><h3>Get your report</h3><p>See the estimated costs, the answers to improve and the next test to run.</p></article></div><button class="pv48-button pv48-primary" data-action="start-real">Start analysis →</button></section>`;
}
function projectPage(){const p=project,c=p.consent;return `<div class="page">${workspaceHead()}<section class="panel project-intake"><div class="panel-heading"><div><h2>What work do you want to improve?</h2><p>Start with one task, such as answering refund requests.</p></div></div><form id="project-form"><div class="formgrid">${field('project-title','Project name',p.title,'For example: Refund support',{full:true,extra:'required maxlength="160"'})}${area('workflow','How does the work happen today?',p.workflow,'Describe the task and what you are considering changing.')}${field('project-owner','Person or role responsible',p.owner,'For example: Support lead',{full:true,extra:'maxlength="100"'})}</div><details><summary>Where your numbers come from</summary><div class="formgrid">${area('baseline-source','Source of your workload numbers',p.baselineSource,'For example: monthly support report, October.')}${area('assumption-source','Source of your estimates',p.assumptionSource,'For example: supplier pricing or a timed trial.')}${area('realization-reason','How would the saved time reduce spending?',p.realizationReason,'For example: fewer paid contractor hours. Add this before counting time as cash savings.')}</div></details>${p.mode==='authorized'?`<details open><summary>Your permission to use the data</summary><p class="small muted">Use approved, redacted business information.</p><div class="formgrid">${field('consent-record','Approval reference',c.record,'Your internal approval or data-access reference',{extra:'required maxlength="200"'})}${field('consent-role','Approving role',c.role,'For example: Support lead',{extra:'required maxlength="200"'})}${field('consent-granted','Permission starts',c.grantedAt,'',{type:'date',extra:'required'})}${field('consent-expires','Permission ends',c.expiresAt,'',{type:'date',extra:'required'})}</div>${check('consent-process','I have permission to use these inputs for this analysis.',c.process)}${check('consent-transfer','I can save and download these inputs and the report.',c.transfer)}<details><summary>Manage existing permission</summary>${check('consent-revoked','Permission has been withdrawn.',c.revoked)}</details></details>`:'<p class="fine topgap">Example data · You can change the values to explore different scenarios.</p>'}<div class="form-actions"><button class="button" type="submit">Continue to costs →</button><button class="button secondary" type="submit" name="next-step" value="validation">Go straight to answers →</button></div></form></section><details class="panel"><summary>Open an existing project</summary><div class="actions">${button('Open saved project','load-local')}${button('Delete saved project','clear-local','quiet')}</div><label class="field topgap" for="project-import">Choose your project file<span>PilotVerdict project JSON · up to 2 MB</span><input id="project-import" type="file" accept=".json,application/json" data-upload="project"></label></details></div>`;}

function workloadRow(r={},i=0){return `<tr data-workload-row><td><label class="visually-hidden" for="category-${i}">Category ${i+1}</label><input id="category-${i}" data-col="category" value="${E(r.category||'')}" maxlength="90" required></td><td><label class="visually-hidden" for="volume-${i}">Monthly contacts ${i+1}</label><input id="volume-${i}" data-col="monthly_tickets" type="number" min="0" max="10000000" step="1" value="${E(r.monthly_tickets??'')}" required></td><td><label class="visually-hidden" for="minutes-${i}">Handling minutes ${i+1}</label><input id="minutes-${i}" data-col="handle_minutes" type="number" min="0" max="1440" step="any" value="${E(r.handle_minutes??'')}" required><input type="hidden" data-col="repeat_rate" value="${E(r.repeat_rate??0)}"><input type="hidden" data-col="escalation_rate" value="${E(r.escalation_rate??0)}"></td><td>${button('Remove','remove-row','quiet smallbtn',`aria-label="Remove category row ${i+1}"`)}</td></tr>`;}
function settingField(meta){const [key,label,hintText]=meta;const value=project.settings[key]*(isPercent.has(key)?100:1);return field(key,label,value,hintText,{type:'number',extra:`required min="${key==='productiveFraction'?5:key==='months'?1:0}" max="${isPercent.has(key)?100:key==='months'?60:key.endsWith('QA')?1440:10000000}" step="${key==='months'?1:'any'}"`});}
function scenarioCards(e){return `<div class="grid3 topgap">${e.scenarios.map(s=>`<article class="scenario ${e.recommendedId===s.id?'preferred':''}">${pill(e.recommendedId===s.id?'Best estimated result':'Alternative',e.recommendedId===s.id?'blue':'')}<h3>${E(s.name)}</h3><div class="value ${s.netHorizon<0?'negative':s.netHorizon>0?'positive':''}">${E(fmtMoney(s.netHorizon))}</div><div class="caption">Estimated net benefit over ${e.s.months} months</div><dl><div><dt>Net time saved / month</dt><dd>${E(fmtNumber(s.signedHours))} h</dd></div><div><dt>Estimated spending avoided / month</dt><dd>${E(fmtMoney(s.avoidableGross))}</dd></div><div><dt>Software cost / month</dt><dd>${E(fmtMoney(s.monthlySpend))}</dd></div><div><dt>Additional labor cost / month</dt><dd>${E(fmtMoney(s.extraLaborCost))}</dd></div><div><dt>One-time cost</dt><dd>${E(fmtMoney(s.setup))}</dd></div><div><dt>Cash savings needed to break even</dt><dd>${s.breakEvenRealization===null?'Not supported':E(percent(s.breakEvenRealization))}</dd></div></dl></article>`).join('')}</div>`;}
function economicsPage(){if(!permissionStatus(project).ok)return `<div class="page">${workspaceHead()}${blocked()}<a class="button" href="#project">Complete setup →</a></div>`;let e=null,error='';try{e=economics(project);}catch(err){error=err.message;}const p=project;return `<div class="page">${workspaceHead()}${blocked()}<section class="panel"><div class="panel-heading"><div><h2>Compare times and costs</h2><p>See what each option would cost using your workload and estimates.</p></div>${pill('USD · monthly baseline','blue')}</div>${e?`<div class="metrics"><div class="metric"><small>Monthly contacts</small><strong>${E(fmtNumber(e.tickets))}</strong><span class="hint">From your workload inputs</span></div><div class="metric"><small>Current handling time</small><strong>${E(fmtNumber(e.laborHours))} h</strong><span class="hint">Volume × handling time, before changes</span></div><div class="metric"><small>Estimated cost of current work</small><strong>${E(fmtMoney(e.baselineCost))}</strong><span class="hint">Based on volume, time and hourly cost</span></div></div>${scenarioCards(e)}<p class="fine">Estimates update when you change your inputs or include correction time.</p>`:`<div class="notice warning"><strong>Add your workload below.</strong>${E(error)}</div>`}</section><section class="panel"><div class="panel-heading"><div><h3>1. Workload baseline</h3><p>List each category once. Include repeat work in its average handling time.</p></div>${button('CSV template','workload-template','quiet smallbtn')}</div><form id="workload-form"><div class="table-wrap"><table><thead><tr><th scope="col">Category</th><th scope="col">Contacts / month</th><th scope="col">Minutes / contact</th><th scope="col">Edit</th></tr></thead><tbody id="workload-rows">${(p.rows.length?p.rows:[{}]).map(workloadRow).join('')}</tbody></table></div><div class="form-actions">${button('+ Add category','add-row')}<button type="submit" class="button">Apply workload</button></div></form><label class="field topgap" for="workload-import">Or import an aggregate CSV<span>Use the CSV template with category totals. Maximum file size: 1 MB.</span><input type="file" id="workload-import" data-upload="workload" accept=".csv,text/csv"></label></section><section class="panel"><div class="panel-heading"><div><h3>2. Your costs and estimates</h3><p>Replace the starting estimates with your own costs and expected time savings.</p></div></div><form id="settings-form"><div class="formgrid">${SETTINGS.slice(0,4).map(settingField).join('')}</div><div class="grid2 topgap"><div><h3>Rules-based automation</h3><div class="formgrid">${SETTINGS.slice(4,9).map(settingField).join('')}</div></div><div><h3>AI assistance</h3><div class="formgrid">${SETTINGS.slice(9,15).map(settingField).join('')}</div></div><details><summary>Additional one-time investments</summary><div class="formgrid">${SETTINGS.slice(15).map(settingField).join('')}</div></details><div class="form-actions"><button type="submit" class="button">Recalculate alternatives</button></div></form></section><details class="panel"><summary>Include correction time from reviewed answers</summary><div class="panel-heading"><div><h3>Connect answer reviews to costs</h3><p>Apply incremental correction time from a fully reviewed sample only when its scope matches the workload.</p></div></div><div class="notice warning compact">Use a fully reviewed sample that matches this task. Include extra correction time only; routine review time is entered above.</div><form id="link-form"><div class="grid2">${['rules','ai'].map(s=>{const l=p.links[s],q=quality(p,s,l.stage);return `<div><h3>${E(labelForScenario(s))}</h3>${check(`link-${s}`,'Include correction work from this reviewed sample',l.enabled)}${select(`link-stage-${s}`,'Sample round',l.stage,stageOptions)}<p class="small muted topgap">${q.n} pass/fail reviews · ${q.fail} failures · ${q.pending+q.inconclusive} unresolved</p>${area(`link-reason-${s}`,'Why does this sample apply?',l.justification,'Scope, selection method, period and representativeness limitations.')}${check(`link-scope-${s}`,'I confirm applicability and that correction time is incremental, without double counting.',l.scopeConfirmed)}</div>`;}).join('')}</div><div class="form-actions"><button type="submit" class="button">Apply quality-to-cost links</button><a class="button quiet" href="#validation">Review answers →</a></div></form></details>${e?`<details class="panel"><summary>Explore different savings assumptions</summary><h3>Sensitivity: how much capacity becomes avoided spend?</h3><p class="small muted">Compare outcomes when different amounts of saved time lead to lower spending.</p><div class="table-wrap"><table><thead><tr><th>Realization</th><th>Rules: ${e.s.months}-month net</th><th>AI: ${e.s.months}-month net</th></tr></thead><tbody>${sensitivity(p).map(x=>`<tr><td>${E(percent(x.rate))}</td><td>${E(fmtMoney(x.rules))}</td><td>${E(fmtMoney(x.ai))}</td></tr>`).join('')}</tbody></table></div></details>`:''}<div class="actions"><a class="button" href="#validation">Continue to answers →</a></div></div>`;}
function caseCard(c){const r=currentReview(project,c);return `<button type="button" class="case-btn" data-action="select-case" data-id="${E(c.id)}" aria-pressed="${caseId===c.id}"><strong>${E(c.id)}</strong><p>${E(c.prompt)}</p>${pill(r?r.outcome:c.review?'stale review':'needs review',r?.outcome==='pass'?'green':r?.outcome==='fail'?'red':'amber')} <span class="small muted">${E(c.candidateVersion)}</span></button>`;}
function caseReview(c){const p=project,r=currentReview(p,c),s=p.sources.find(x=>x.id===c.sourceId),h=hint(p,c);return `<section class="panel"><div class="panel-heading"><div><h3>${E(c.id)}</h3><p>${E(labelForScenario(c.scenario))} · ${E(c.stage)} · ${E(c.candidateVersion)} · ${E(c.severity)} severity</p></div>${pill(r?`Review result: ${r.outcome}`:'Review needed',r?.outcome==='pass'?'green':r?.outcome==='fail'?'red':'amber')}</div><div class="split-label">PROMPT</div><p class="quote">${E(c.prompt)}</p><div class="split-label">RECORDED OUTPUT</div><p class="quote">${E(c.response)}</p><div class="split-label">APPROVED SOURCE · ${E(s.name)} · ${E(s.version)}</div><p class="quote source-quote">${E(s.text)}</p><p class="small"><strong>Criterion:</strong> ${E(s.criterion)}</p><div class="notice ${h.status==='potential-conflict'?'warning':''}"><strong>${E(h.label)}</strong>${E(h.reason)}<br>Check this signal against the rule, then record your review.</div>${c.review&&!r?'<div class="notice warning">The answer, rule or change has been updated. Review this answer again.</div>':''}<form id="review-form"><input type="hidden" name="case-id" value="${E(c.id)}"><div class="formgrid">${select('review-outcome','Your verdict',r?.outcome||'',[['','Choose a verdict'],['pass','Pass — meets the stated criterion'],['fail','Fail — violates the stated criterion'],['inconclusive','Inconclusive — evidence is insufficient']])}${field('review-by','Reviewer role',r?.by||'','Who reviewed this answer?',{extra:'required maxlength="100"'})}${area('review-quote','Exact quote supporting your judgment',r?.quote||'','Copy text exactly from the recorded output.')}${area('review-reason','Why does this meet or violate the source?',r?.reason||'','Include applicability, exceptions and any missing evidence.')}${field('review-minutes','Additional correction minutes',r?.correctionMinutes??'','For failures: incremental rework beyond review time already modeled. Blank = unknown.',{type:'number',full:true,extra:'min="0" max="1440" step="any"'})}</div><div class="form-actions"><button type="submit" class="button">Save review</button>${c.stage==='baseline'?button('Prepare paired retest','prepare-retest','secondary',`data-id="${E(c.id)}"`):''}${button('Delete case','delete-case','quiet',`data-id="${E(c.id)}"`)}</div></form></section>`;}
function casesPanel(){const p=project,q=quality(p,scenarioFilter,stageFilter);const cases=p.cases.filter(c=>c.scenario===scenarioFilter&&c.stage===stageFilter);if(!cases.some(c=>c.id===caseId))caseId=cases[0]?.id||null;const c=cases.find(x=>x.id===caseId);return `<div class="toolbar"><div class="actions">${select('scenario-filter','Alternative',scenarioFilter,[['ai','AI assistance'],['rules','Rules-based automation']])}${select('stage-filter','Review round',stageFilter,stageOptions)}</div><div>${pill(q.status,q.meets?'green':q.critical?'red':'amber')}</div></div><div class="metrics"><div class="metric"><small>Answers reviewed</small><strong>${q.pass} pass / ${q.fail} fail</strong><span class="hint">${q.pending} pending or stale · ${q.inconclusive} inconclusive</span></div><div class="metric"><small>Reviewed-case pass rate</small><strong>${E(percent(q.passRate))}</strong><span class="hint">Based on ${q.n} reviewed answers</span></div><div class="metric"><small>Your review target</small><strong>${p.criteria.minCases} cases</strong><span class="hint">${E(percent(p.criteria.minPassRate))} pass target · no critical failures</span></div></div>${c?`<div class="review-layout"><aside class="case-list" aria-label="Recorded cases">${cases.map(caseCard).join('')}</aside><div>${caseReview(c)}</div></div>`:`<div class="empty"><h3>No cases in this round yet.</h3><p>Approve a source, add a recorded response, and make a human judgment against the exact criterion.</p>${button('Add cases','tab-add','')}${button('Manage sources','tab-sources')}</div>`}`;}
function sourcesPanel(){const p=project,s=p.sources.find(v=>v.id===sourceEdit)||{id:'',name:'',version:'1.0',text:'',criterion:'',kind:'human',token:'',limit:null,approved:false,approvedBy:''};return `<section class="panel"><div class="panel-heading"><div><h3>Your rules and evaluation criteria</h3><p>Every output review references an explicit source and version. Changed sources invalidate earlier reviews.</p></div></div>${p.sources.length?`<div class="table-wrap"><table><thead><tr><th>Source</th><th>Version</th><th>Approval</th><th>Screening</th><th>Edit</th></tr></thead><tbody>${p.sources.map(v=>`<tr><td><strong>${E(v.name)}</strong><br>${E(v.id)}</td><td>${E(v.version)}</td><td>${E(v.approved?v.approvedBy:'Not approved')}</td><td>${E(v.kind)}</td><td>${button('Edit / version','edit-source','quiet smallbtn',`data-id="${E(v.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">No sources yet. Add one exact, approved excerpt below.</p>'}</section><section class="panel"><h3>${sourceEdit?'Update the source — earlier reviews become stale':'Add an approved source'}</h3><form id="source-form"><div class="formgrid">${field('source-id','Stable source ID',s.id,'Letters, numbers, hyphens or underscores',{extra:`required maxlength="100" ${sourceEdit?'readonly':''}`})}${field('source-name','Source name',s.name,'Policy, rubric or documented requirement',{extra:'required maxlength="160"'})}${field('source-version','Version',s.version,'Example: 1.0 or 2026-11-20',{extra:'required maxlength="60"'})}${field('source-approver','Approving role',s.approvedBy,'Who is responsible for the criterion?',{extra:'required maxlength="100"'})}${area('source-text','Exact source excerpt',s.text,'Copy authorized wording. Do not paste personal data or credentials.')}${area('source-criterion','What must the output do?',s.criterion,'A concrete, reviewable expectation, including exceptions.')}${select('source-kind','Optional screening check',s.kind,[['human','Human assessment only'],['contains','Expected phrase'],['not_contains','Prohibited phrase'],['max_usd','Explicit USD amount threshold']])}${field('source-token','Phrase to check',s.token,'For phrase checks, enter the exact words to look for.',{extra:'maxlength="200"'})}${field('source-limit','USD threshold',s.limit??'','For amount checks. Must appear explicitly in the source.',{type:'number',extra:'min="0" max="1000000" step="any"'})}</div>${check('source-approved','The responsible source owner has approved this excerpt and evaluation criterion.',s.approved)}<div class="form-actions"><button type="submit" class="button">${sourceEdit?'Update source':'Add source'}</button>${sourceEdit?button('Cancel edit','cancel-source','quiet'):''}</div></form></section>`;}
function addCasesPanel(){const p=project,d=caseDraft||{id:'',sourceId:p.sources[0]?.id||'',scenario:scenarioFilter,stage:'baseline',parentId:'',candidateVersion:'v1',prompt:'',response:'',severity:'major'};return `<section class="panel"><h3>Add a recorded output</h3><p class="small muted">Paste an answer you want to check and choose the rule it should follow.</p>${!p.sources.length?'<div class="notice warning">Add an approved source first. <button type="button" class="button quiet smallbtn" data-action="tab-sources">Open sources →</button></div>':''}<form id="case-form"><div class="formgrid">${field('case-id','Case ID',d.id,'Unique within this project',{extra:'required maxlength="100"'})}${select('case-source','Source',d.sourceId,p.sources.length?p.sources.map(s=>[s.id,`${s.name} (${s.version})`]):[['','Add a source first']])}${select('case-scenario','Alternative',d.scenario,[['ai','AI assistance'],['rules','Rules-based automation']])}${select('case-stage','Round',d.stage,stageOptions)}${field('case-version','Candidate version',d.candidateVersion,'Retests must match the approved change',{extra:'required maxlength="80"'})}${select('case-parent','Paired baseline ID',d.parentId,[['','None / not paired'],...p.cases.filter(c=>c.stage==='baseline').map(c=>[c.id,c.id])])}${select('case-severity','Failure severity',d.severity,[['minor','Minor'],['major','Major'],['critical','Critical — blocks readiness']])}${area('case-prompt','Prompt or task',d.prompt,'After changes must repeat the exact baseline prompt.')}${area('case-response','Recorded output',d.response,'Paste the answer with personal details removed. Review it in the next step.')}</div><div class="form-actions"><button type="submit" class="button">Add case for review</button></div></form></section><section class="panel"><div class="panel-heading"><div><h3>Import a batch of recorded outputs</h3><p>Import up to 200 answers using the template, then review them here.</p></div>${button('Case CSV template','case-template','quiet smallbtn')}</div><label class="field" for="case-import">Case CSV<input type="file" id="case-import" data-upload="cases" accept=".csv,text/csv"></label></section>`;}
function changePanel(){const p=project,f=p.fixes[scenarioFilter]||{scenario:scenarioFilter,version:'v2',description:'',rollback:'',owner:'',approved:false};return `<section class="panel"><h3>Describe your change</h3><p class="small muted">Describe the correction and record who approved it. Then add new answers to check the change.</p><form id="fix-form"><div class="formgrid">${select('fix-scenario','Alternative',f.scenario,[['ai','AI assistance'],['rules','Rules-based automation']])}${field('fix-version','New candidate version',f.version,'Different from baseline',{extra:'required maxlength="80"'})}${field('fix-owner','Approving owner role',f.owner,'Who owns the change?',{full:true,extra:'required maxlength="100"'})}${area('fix-description','What changes?',f.description,'Describe the exact rule, instruction or workflow correction.')}${area('fix-rollback','When should the change be rolled back?',f.rollback,'Describe the specific problem that would make you stop the change.')}</div>${check('fix-approved','The responsible owner approved this scoped change.',f.approved)}<div class="form-actions"><button type="submit" class="button">Record approval</button></div></form></section><section class="panel"><h3>Check the change</h3><div class="grid2"><div><p><strong>After changes</strong></p><p class="small muted">Use the same prompt, alternative and source as a baseline case. Select the baseline ID when adding the new output.</p></div><div><p><strong>Extra checks</strong></p><p class="small muted">Try new questions to see how the updated workflow handles different cases.</p></div></div>${button('Add new-version outputs →','tab-add','')}</section><section class="panel"><h3>Choose your review targets</h3><p class="small muted">Set how many answers to review and the pass rate you need. Resolve open reviews and critical problems before meeting the target.</p><form id="criteria-form"><div class="formgrid">${field('minimum-cases','Minimum resolved cases',p.criteria.minCases,'Whole number, 1–200',{type:'number',extra:'required min="1" max="200" step="1"'})}${field('minimum-pass','Minimum pass rate (%)',p.criteria.minPassRate*100,'0–100; chosen before interpreting results where possible',{type:'number',extra:'required min="0" max="100" step="any"'})}</div><div class="form-actions"><button class="button secondary" type="submit">Save declared criteria</button></div></form></section>`;}
function validationPage(){if(!permissionStatus(project).ok)return `<div class="page">${workspaceHead()}${blocked()}<a class="button" href="#project">Complete setup →</a></div>`;return `<div class="page">${workspaceHead()}${blocked()}<div class="panel-heading"><div><h2>Check answers</h2><p>Compare each answer with your rule, record the result and test the next version.</p></div><a class="button secondary" href="#economics">Include correction time in costs</a></div><div class="tabs" role="group" aria-label="Validation sections">${[['cases','Review answers'],['sources','Your rules'],['add','Add answers'],['change','Improve & retest']].map(([v,t])=>`<button type="button" data-action="tab-${v}" aria-pressed="${validationTab===v}">${t}</button>`).join('')}</div>${validationTab==='sources'?sourcesPanel():validationTab==='add'?addCasesPanel():validationTab==='change'?changePanel():casesPanel()}<div class="actions"><a class="button" href="#decision">Continue to results →</a></div></div>`;}
function decisionPage(){if(!permissionStatus(project).ok)return `<div class="page">${workspaceHead()}${blocked()}<a class="button" href="#project">Complete setup →</a></div>`;const p=project;let d=null,error='';try{d=decision(p);}catch(err){error=err.message;}return `<div class="page">${workspaceHead()}${blocked()}${d?`<section class="decision-hero"><div class="kicker">YOUR RESULTS</div><h2>${E(d.title)}</h2><p>${E(d.text)}</p><div class="next"><strong>Next test:</strong> ${E(d.next)}</div></section><div class="grid2"><section class="panel"><h3>Economic preference</h3><p><strong>${E(labelForScenario(d.economics.recommendedId))}</strong></p><p class="small muted">${p.settings.months}-month horizon. ${E(percent(p.settings.realizationRate))} assumed realization of released capacity. All values remain modeled.</p><a href="#economics" class="small">Inspect every assumption →</a></section><section class="panel"><h3>New-version output evidence</h3>${['rules','ai'].map(s=>{const q=quality(p,s,'retest');return `<p class="small"><strong>${E(labelForScenario(s))}</strong><br>${q.pass} pass · ${q.fail} fail · ${q.pending+q.inconclusive} unresolved · ${E(q.status)}</p>`;}).join('')}<a href="#validation" class="small">Inspect case-level evidence →</a></section></div>`:`<div class="notice warning"><strong>A supported decision needs workload inputs and active permission.</strong>${E(error)} <a href="#economics">Open the model →</a></div>`}<section class="panel"><h3>Make the next step measurable</h3><p class="small muted">Save the baseline, target and failure rule before running a real test. Observed outcomes stay separate from projected benefits.</p><form id="plan-form"><div class="formgrid">${field('plan-owner','Accountable owner / role',p.plan.owner,'Who makes the decision?',{extra:'maxlength="100"'})}${field('plan-metric','Primary success metric',p.plan.metric,'Example: minutes to a documented decision',{extra:'maxlength="300"'})}${area('plan-baseline','Before change / comparison method',p.plan.baseline,'Current spreadsheet + manual review, on comparable cases.',false)}${area('plan-target','Success threshold',p.plan.target,'What result would make this test successful?',false)}${area('plan-stop','Stop / failure rule',p.plan.stop,'What would cause you to reject or reverse this approach?',false)}${area('plan-test','Next validation test',p.plan.nextTest,'Specify users, cases, method and review process.',false)}${area('plan-decision','Owner decision and reasoning',p.plan.decision,'Record your choice and why you made it.')}${area('plan-observed','Observed result — only after the test',p.plan.observedResult,'Record what happened when you ran the test.')}</div><div class="form-actions"><button type="submit" class="button">Save action plan</button></div></form></section><section class="panel"><div class="panel-heading"><div><h3>One report, with the evidence behind it</h3><p>Includes economics, assumptions, source excerpts, review reasons, correction and the next test.</p></div>${pill('Your download','amber')}</div><p class="fine">Downloads include your inputs and review notes. Share them with people who have permission to see them.</p><div class="actions">${button('Download report','export-report','')}${button('Download project','export-project')}</div></section><details><summary>Project history (${p.history.length} events)</summary><p class="small muted">Your recorded changes and decisions.</p><ol class="history-list">${p.history.slice(-12).reverse().map(h=>`<li><strong>${E(h.type)}</strong> · ${E(h.at)}<br>${E(h.detail)}</li>`).join('')}</ol></details></div>`;}
function methodPage(){return `<div class="page"><article class="prose"><p class="kicker">HOW IT WORKS</p><h1>The numbers and rules behind your result.</h1><h2>Compare the same task three ways</h2><p>PilotVerdict compares your current process with rules-based automation and AI assistance. Your workload, hourly cost, software prices, expected time savings and review effort drive the calculation.</p><details open><summary>How costs are calculated</summary><p>Monthly work is the number of tasks multiplied by the time per task. From the time saved, we subtract routine review and any extra correction work you include.</p><code>Net time saved = time saved by automation − review time − extra correction time
Estimated net benefit = spending avoided − software costs − extra labor costs − setup costs</code><p>The share of saved time that reduces spending is your assumption. It starts at zero. Negative time savings add a labor cost instead of disappearing from the comparison.</p></details><details><summary>How answers are checked</summary><p>You provide the rule, the answer and what a correct answer should do. Optional phrase and amount checks highlight details to review. You record the result with a reason and an exact quote. Changing a source or answer makes its earlier review out of date.</p></details><details><summary>How improvements affect the result</summary><p>Record the change, check the new version with the same questions, then add fresh questions. A complete reviewed sample can supply extra correction time to the cost comparison when you confirm that the sample fits the task. The report keeps estimated benefits and observed results separate.</p></details><details><summary>Your data and saved projects</summary><p>Your inputs are processed in this browser. Saving is explicit: Save project stores a copy in your browser profile, and Download creates a file. Those copies contain your inputs and are readable by someone with access to the profile or file.</p><p>Use information you have permission to process. Recorded permission has an expiry date and can be withdrawn. Downloads require permission to save and export.</p><p>The page is served by GitHub Pages. The Aleo and Host Grotesk typefaces are requested from Google Fonts. These services receive normal connection information; the application sends them no project inputs. The app uses no analytics tracker or AI API.</p></details><details><summary>About the calculation engine</summary><p>The original PilotVerdict cost and CSV modules are preserved from revision ${BASE_COMMIT.slice(0,7)}. The shared-project layer adds input checks, correction costs, answer reviews, retests and reporting. The source includes reproducible unit and browser tests.</p></details><div class="actions"><a href="#${project?'project':'home'}" class="button secondary">${project?'Return to your project':'Back to PilotVerdict'}</a></div></article></div>`;}
function storyPage(){return `<div class="page"><article class="prose"><p class="kicker">STUTI JOHRI · PRODUCT PROJECT</p><h1>PilotVerdict</h1><p>Compare the cost of a workflow with and without automation, check answers against approved rules, and keep the next decision in one report.</p><h2>The problem</h2><p>A lower handling time can look attractive until review and correction work are included. Teams need to see both the costs and the answers behind a proposed change.</p><h2>The product</h2><p>One shared project connects workload inputs, cost comparisons, source-linked answer reviews and retests. Teams can use rules-based automation as an alternative to AI, enter new data, save their work and export their findings.</p><h2>Design choices</h2><p>A guided four-step flow, plain-language labels, detailed settings when needed, and calculations tied to editable inputs. The example uses sample data so visitors can try the full journey immediately.</p><h2>Development</h2><p>Developed for Stuti Johri's product project with collaboration from Nicolò Bonacorsi and AI-assisted engineering. The demo and source show the implemented capabilities; customer use and business results will be added as they are measured.</p><div class="actions">${button('Try the example','load-demo','')}<a class="button secondary" href="../">Stuti's portfolio</a></div></article></div>`;}

function render(){
 document.body.dataset.route=route;
 const top=$('start-header');if(top){top.textContent=project?'Your project →':'Start analysis →';top.dataset.action=project?'resume-work':'start-real';}

 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(['project','economics','validation','decision'].includes(route)&&!project)project=newProject();
 try{root.innerHTML=route==='home'?home():route==='project'?projectPage():route==='economics'?economicsPage():route==='validation'?validationPage():route==='decision'?decisionPage():route==='method'?methodPage():storyPage();}
 catch(e){root.innerHTML=`<div class="page">${project?workspaceHead():''}<div class="notice error"><strong>Unable to render this view.</strong>${E(e.message)}</div><a class="button secondary" href="#project">Return to project</a></div>`;}
 document.title=`PilotVerdict — ${route==='home'?'Know the cost. Check the answers.':route==='economics'?'Compare times and costs':route==='validation'?'Check answers':route==='decision'?'Decision record':route==='story'?'Project story':route==='method'?'Method':'Your project'}`;
}

root.addEventListener('input',e=>{if(e.target.closest('form'))dirty=true;});
document.addEventListener('click',e=>{
 const link=e.target.closest('a[href^="#"]');if(link&&link.getAttribute('href')!=='#main'&&dirty){if(!window.confirm('There are unapplied edits. Leave this form without applying them?')){e.preventDefault();return;}dirty=false;}
});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a.startsWith('tab-')){if(dirty&&!window.confirm('Discard unapplied form edits?'))return;dirty=false;validationTab=a.slice(4);render();return;}
 switch(a){
  case 'peek-costs':case 'peek-answers':case 'peek-next':{const key=a.slice(5);root.querySelectorAll('[data-peek]').forEach(x=>x.hidden=x.dataset.peek!==key);root.querySelectorAll('[data-action^="peek-"]').forEach(x=>{const active=x.dataset.action===a;x.setAttribute('aria-pressed',String(active));x.classList.toggle('pv48-peek-active',active);});break;}
  case 'how-it-works':{if(route!=='home'){routeTo('home');setTimeout(()=>document.getElementById('how-it-works')?.scrollIntoView(),60);}else document.getElementById('how-it-works')?.scrollIntoView();break;}
  case 'resume-work':routeTo(project?'project':'home');break;
  case 'start-real':case 'new-project':start(false);break;
  case 'load-demo':loadDemo();break;
  case 'open-economics':case 'open-validation':if(!project){start(false);notify('Set up your project first. Then choose costs or answers.');}else routeTo(a==='open-economics'?'economics':'validation');break;
  case 'save-local':{const data=serializeProject(project);localStorage.setItem(STORAGE_KEY,data);notify('Project saved in this browser.');break;}
  case 'load-local':{if(!confirmReplace())return;const text=localStorage.getItem(STORAGE_KEY);if(!text)throw new Error('There is no integrated project saved in this browser.');commit(importProject(text),'Saved project opened.','project');break;}
  case 'clear-local':if(window.confirm('Permanently delete the integrated project saved in this browser? The current tab is not cleared.')){localStorage.removeItem(STORAGE_KEY);notify('Saved project deleted from this browser.');}break;
  case 'export-project':download('pilotverdict-project.json',serializeProject(project),'application/json');notify('Project downloaded.');break;
  case 'export-report':download('pilotverdict-decision-report.html',reportHTML(project),'text/html');notify('Report downloaded.');break;
  case 'add-row':{const rows=$('workload-rows');if(rows.children.length>=250)throw new Error('Maximum 250 categories.');rows.insertAdjacentHTML('beforeend',workloadRow({},Date.now()));dirty=true;break;}
  case 'remove-row':b.closest('tr').remove();dirty=true;break;
  case 'workload-template':download('pilotverdict-workload-template.csv','category,monthly_tickets,handle_minutes,repeat_rate,escalation_rate\nFictional category,1000,8,0,0\n','text/csv');break;
  case 'case-template':{const sid=project.sources[0]?.id||'approved-source';download('pilotverdict-case-template.csv',`id,source_id,scenario,stage,parent_id,candidate_version,prompt,response\nnew-case-01,${sid},ai,baseline,,v1,Replace with an authorized test prompt,Replace with the recorded output\n`,'text/csv');break;}
  case 'select-case':if(dirty&&!window.confirm('Discard unapplied review edits?'))return;dirty=false;caseId=b.dataset.id;render();break;
  case 'edit-source':sourceEdit=b.dataset.id;validationTab='sources';render();break;
  case 'cancel-source':sourceEdit=null;dirty=false;render();break;
  case 'prepare-retest':{const c=project.cases.find(x=>x.id===b.dataset.id);if(!project.fixes[c.scenario]?.approved)throw new Error('Record your change in Improve & retest first.');caseDraft={...c,id:'',parentId:c.id,stage:'retest',candidateVersion:project.fixes[c.scenario].version,response:'',review:null};validationTab='add';dirty=false;render();break;}
  case 'delete-case':{requirePermission(project);const id=b.dataset.id;if(project.cases.some(c=>c.parentId===id))throw new Error('Delete paired retests before removing their baseline.');if(window.confirm(`Delete ${id}? Its review will also be removed.`)){let q=structuredClone(project);q.cases=q.cases.filter(c=>c.id!==id);commit(record(q,'case-deleted',id),'Case deleted. Any enabled quality link will be recalculated.');}break;}
 }
}catch(err){fail(err);}});
root.addEventListener('change',async event=>{const t=event.target;try{
 if(t.id==='scenario-filter'||t.id==='stage-filter'){scenarioFilter=$('scenario-filter').value;stageFilter=$('stage-filter').value;caseId=null;dirty=false;render();return;}
 if(t.id==='case-stage'){$('case-version').value=t.value==='baseline'?'v1':project.fixes[$('case-scenario').value]?.version||'';if(t.value!=='retest')$('case-parent').value='';}
 if(t.id==='case-parent'&&t.value){const c=project.cases.find(x=>x.id===t.value);if(c){$('case-prompt').value=c.prompt;$('case-source').value=c.sourceId;$('case-scenario').value=c.scenario;$('case-stage').value='retest';$('case-version').value=project.fixes[$('case-scenario').value]?.version||'';}}
 if(!t.dataset.upload)return;const file=t.files?.[0];if(!file)return;
 try{if(file.size>(t.dataset.upload==='project'?2_000_000:1_000_000))throw new Error('File exceeds the supported size limit.');if(t.dataset.upload!=='project')requirePermission(project);const text=await file.text();
 if(t.dataset.upload==='project'){const q=importProject(text);if(!confirmReplace())return;commit(q,'Project opened and recalculated.','project');}
 else if(t.dataset.upload==='workload'){const q=structuredClone(project);q.rows=parseWorkloadCSV(text);commit(record(q,'workload-imported',`${q.rows.length} aggregate categories; local file processing.`),'CSV opened. Your results are updated.');}
 else {const q=addCases(project,parseCaseCSV(text));validationTab='cases';commit(q,'Answers imported. Review them against your rules.');}
 }finally{t.value='';}
}catch(err){fail(err);}});
root.addEventListener('submit',event=>{event.preventDefault();const form=event.target,f=new FormData(form),get=k=>String(f.get(k)??''),yes=k=>f.get(k)==='on';try{
 let q=structuredClone(project);
 switch(form.id){
  case 'project-form':{
   q.title=get('project-title');q.workflow=get('workflow');q.owner=get('project-owner');q.baselineSource=get('baseline-source');q.assumptionSource=get('assumption-source');q.realizationReason=get('realization-reason');
   if(q.mode==='authorized')q.consent={record:get('consent-record'),role:get('consent-role'),grantedAt:get('consent-granted'),expiresAt:get('consent-expires'),process:yes('consent-process'),transfer:yes('consent-transfer'),revoked:yes('consent-revoked')};
   q=record(validateProject(q),'project-defined','Workflow, provenance and operator permission record updated.');
   const status=permissionStatus(q);commit(q,status.ok?'Project saved. Add the workload baseline next.':status.reason,status.ok?(event.submitter?.value==='validation'?'validation':'economics'):'project');break;
  }
  case 'workload-form':{
   requirePermission(q);q.rows=strictRows([...form.querySelectorAll('[data-workload-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-col]')].map(el=>[el.dataset.col,el.value]))));if(!q.rows.length)throw new Error('Add at least one workload category.');commit(record(q,'workload-updated',`${q.rows.length} aggregate categories.`),'Workload updated. All alternatives recalculated.');break;
  }
  case 'settings-form':{
   requirePermission(q);const raw={...q.settings};for(const [key] of SETTINGS){const v=get(key);raw[key]=isPercent.has(key)?(v.trim()===''?'':Number(v)/100):v;}q.settings=strictSettings(raw);economics(q);commit(record(q,'economics-assumptions-updated','Model assumptions changed; not observed results.'),'Estimates updated.');break;
  }
  case 'link-form':{
   requirePermission(q);for(const s of ['ai','rules'])q.links[s]={enabled:yes(`link-${s}`),stage:get(`link-stage-${s}`),justification:get(`link-reason-${s}`),scopeConfirmed:yes(`link-scope-${s}`)};economics(q);commit(record(q,'quality-cost-link-updated','Explicit sample extrapolation settings updated.'),'Quality-to-cost links applied.');break;
  }
  case 'source-form':{
   requirePermission(q);const s=validateSource({id:get('source-id'),name:get('source-name'),version:get('source-version'),text:get('source-text'),criterion:get('source-criterion'),kind:get('source-kind'),token:get('source-token'),limit:get('source-limit'),approved:yes('source-approved'),approvedBy:get('source-approver')});
   if(sourceEdit){q.sources=q.sources.map(v=>v.id===sourceEdit?s:v);q=record(q,'source-updated',`${s.id} ${s.version}; earlier review snapshots may be stale.`);}else q=addSource(q,s);
   sourceEdit=null;validationTab='add';commit(q,'Rule saved. Add the answers you want to check.');break;
  }
  case 'case-form':{
   const c={id:get('case-id'),sourceId:get('case-source'),scenario:get('case-scenario'),stage:get('case-stage'),parentId:get('case-parent'),candidateVersion:get('case-version'),prompt:get('case-prompt'),response:get('case-response'),severity:get('case-severity')};q=addCases(q,[c]);caseDraft=null;validationTab='cases';scenarioFilter=c.scenario;stageFilter=c.stage;caseId=c.id;commit(q,'Output added. Review its source and record a human verdict.');break;
  }
  case 'review-form':{
   q=reviewCase(q,get('case-id'),{outcome:get('review-outcome'),by:get('review-by'),reason:get('review-reason'),quote:get('review-quote'),correctionMinutes:get('review-minutes')});commit(q,'Review saved. Your results now include it.');break;
  }
  case 'fix-form':q=approveFix(q,{scenario:get('fix-scenario'),version:get('fix-version'),description:get('fix-description'),rollback:get('fix-rollback'),owner:get('fix-owner'),approved:yes('fix-approved')});commit(q,'Change recorded. Add the new answers to check it.');break;
  case 'criteria-form':requirePermission(q);q.criteria={minCases:Number(get('minimum-cases')),minPassRate:Number(get('minimum-pass'))/100};q=validateProject(q);commit(record(q,'criteria-updated','User-selected acceptance criteria changed; not a certification standard.'),'Declared acceptance criteria saved.');break;
  case 'plan-form':requirePermission(q);q.plan={owner:get('plan-owner'),metric:get('plan-metric'),baseline:get('plan-baseline'),target:get('plan-target'),stop:get('plan-stop'),nextTest:get('plan-test'),decision:get('plan-decision'),observedResult:get('plan-observed')};commit(record(validateProject(q),'decision-plan-updated','Owner plan and operator-reported observations saved.'),'Action plan saved.');break;
 }
}catch(err){fail(err);}});
